package com.splendordashboard;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;
public class SettingsActivity extends Activity{AppPrefs p;LinearLayout box;
 public void onCreate(Bundle b){super.onCreate(b);p=new AppPrefs(this);build();}
 TextView label(String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(18);t.setPadding(18,16,18,10);return t;}
 EditText field(String title,float val,String key){box.addView(label(title));EditText e=new EditText(this);e.setText(String.valueOf(val));e.setTextColor(Color.WHITE);e.setTextSize(18);e.setSingleLine();e.setInputType(2|8192);e.setPadding(18,4,18,12);e.setOnFocusChangeListener((v,f)->{if(!f)try{p.set(key,Float.parseFloat(e.getText().toString()));}catch(Exception ignored){}});box.addView(e);return e;}
 void toggle(String title,String key,boolean val){Switch s=new Switch(this);s.setText(title);s.setTextColor(Color.WHITE);s.setTextSize(18);s.setPadding(18,12,18,12);s.setChecked(val);s.setOnCheckedChangeListener((b,c)->p.set(key,c));box.addView(s);}
 void build(){ScrollView sc=new ScrollView(this);box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(12,8,12,24);box.setBackgroundColor(Color.rgb(5,7,8));sc.addView(box);TextView h=label("SPLENDOR SMART DASHBOARD  •  SETTINGS");h.setTextSize(24);box.addView(h);field("Tank capacity (L)",p.tank(),"tank");field("Mileage (km/L)",p.mileage(),"mileage");field("Reserve (L)",p.reserve(),"reserve");field("Maximum display range (km)",p.maxRange(),"maxRange");field("Gauge maximum speed (km/h)",p.gaugeMax(),"gaugeMax");toggle("Keep screen awake","awake",p.awake());toggle("Fullscreen dashboard","fullscreen",p.fullscreen());toggle("Auto-start dashboard when charging/boot is requested","autoStart",p.autoStart());toggle("Auto-start trip","autoTrip",p.autoTrip());toggle("Save trip history","saveHistory",p.saveHistory());toggle("Show clock","clock",p.showClock());toggle("Show battery","battery",p.showBattery());toggle("Show GPS status","gps",p.showGps());toggle("Show compass","compass",p.showCompass());toggle("DEMO MODE","demo",p.demo());field("Demo speed (km/h)",p.demoSpeed(),"demoSpeed");Button diag=new Button(this);diag.setText("OPEN DIAGNOSTICS");diag.setOnClickListener(v->startActivity(new android.content.Intent(this,DiagnosticsActivity.class)));box.addView(diag);Button done=new Button(this);done.setText("SAVE & RETURN");done.setOnClickListener(v->{finish();});box.addView(done);setContentView(sc);}}